package app.readaloud

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Test

// Text.kt must match extension/segment.js. Expected values in text-cases.json are generated by
// running segment.js under node (see android/AGENTS notes in the repo AGENTS.md).
class TextTest {
    @Test fun matchesSegmentJs() {
        val j = JSONObject(javaClass.classLoader!!.getResource("text-cases.json")!!.readText())
        val rules = Text.parseLex(j.getString("lex"))
        val out = j.getJSONArray("out")
        for (k in 0 until out.length()) {
            val o = out.getJSONObject(k)
            val c = o.getString("c")
            val want = o.getJSONArray("segs").let { a -> (0 until a.length()).map { a.getJSONArray(it).let { p -> p.getInt(0) to p.getInt(1) } } }
            assertEquals("segments of: $c", want, Text.segments(c).map { it.start to it.end })
            assertEquals("lex of: $c", o.getString("lex"), Text.lex(c, rules, true))
        }
    }
}
